    \dfrac{3}{- x - 3y + 4} + \dfrac{5}{- 5x + 4y - 3} = - \dfrac{49}{80}
\end{cases}$ là:  
\choice
{ \True   $(x;y)=\left( 5 ; 3 \right)$  }	   { $(x;y)=\left(5 ; \dfrac{5}{2}\right)$  }	     { $(x;y)=\left( \dfrac{9}{2} ; 3  \right)$   }	   { $(x;y)=\left( \dfrac{9}{2} ; \dfrac{5}{2} \right)$  }
\loigiai{
Vậy hệ phương trình có nghiệm duy nhất $(x; y) = (5; 3)$.
}\end{ex}

